import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { installDeprecatedToolCallRewrites } from "bitfab-lib/deprecated-tool-names";
import { installToolParameterWarnings, toolConfig, } from "bitfab-lib/mcp-contract";
import { createBitfabToolHandlers, } from "./bitfabToolHandlers.js";
import { buildMcpInstructions, findWaitCommand } from "./mcpInstructions.js";
export function createMcpServer(platform, getConfig, pluginVersion, waitCommand) {
    const { proxy, handlers } = createBitfabToolHandlers(platform, getConfig, pluginVersion);
    const server = new McpServer({
        name: "Bitfab",
        version: pluginVersion,
    }, { instructions: buildMcpInstructions(platform, waitCommand) });
    for (const { contract, handle } of handlers) {
        server.registerTool(contract.name, toolConfig(contract), async (args) => handle(args));
    }
    installToolParameterWarnings(server.server, handlers.map(({ contract }) => contract), `Bitfab plugin ${pluginVersion}`);
    installDeprecatedToolCallRewrites(server.server);
    return { server, proxy };
}
export async function startMcpServer(platform, getConfig, pluginVersion) {
    const { server } = createMcpServer(platform, getConfig, pluginVersion, findWaitCommand(process.argv[1]));
    const transport = new StdioServerTransport();
    await server.connect(transport);
}
